export function getAhmedabadProjectBySlug(slug) {
  if (!slug) return null;
  const clean = String(slug).toLowerCase().trim();
  return AHMEDABAD_REGISTRY_PROJECTS.find(p => {
    return p.slug.toLowerCase() === clean || 
           String(p.id) === clean || 
           p.slug.replace(/-pid-\d+$/, '').toLowerCase() === clean ||
           p.name.toLowerCase().replace(/[^a-z0-9]+/g, '-') === clean;
  }) || null;
}

export const AHMEDABAD_ALL_SLUGS = AHMEDABAD_REGISTRY_PROJECTS.map(p => p.slug);

export const AHMEDABAD_PROJECT_COORDINATES = Object.fromEntries(
  AHMEDABAD_REGISTRY_PROJECTS.map(p => [
    p.slug,
    {
      lat: p.lat,
      lng: p.lng,
      locality: p.locality,
      city: "ahmedabad",
      cityName: "Ahmedabad",
      propertyType: p.type || "Apartment",
      verified: true
    }
  ])
);
